import fs from "node:fs";
import path from "node:path";

const GENERATED_TELEPROMPTER_BANNER =
  "<!-- GENERATED FILE. DO NOT EDIT. Edit apps/anvil/teleprompter_pro.html -->";

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDir(s, d);
    } else {
      fs.copyFileSync(s, d);
    }
  }
}

function emptyDir(dir) {
  if (!fs.existsSync(dir)) return;
  for (const name of fs.readdirSync(dir)) {
    fs.rmSync(path.join(dir, name), { recursive: true, force: true });
  }
}

function stripGeneratedBanner(html) {
  return html.replace(
    /^<!-- GENERATED FILE\. DO NOT EDIT\. Edit apps\/anvil\/teleprompter_pro\.html -->\r?\n?/,
    "",
  );
}

function tagGeneratedTeleprompter(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`[sync-anvil] missing expected file: ${filePath}`);
  }
  const html = fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, "");
  const normalized = stripGeneratedBanner(html);
  const newline = normalized.includes("\r\n") ? "\r\n" : "\n";
  const tagged = `${GENERATED_TELEPROMPTER_BANNER}${newline}${normalized}`;
  fs.writeFileSync(filePath, tagged, "utf8");
}

function writeGeneratedReadme(destDir) {
  const readmePath = path.join(destDir, "GENERATED.md");
  const body = `# Generated Mirror

This folder is generated by \`pnpm --filter nursery sync:anvil\`.

- Source of truth HTML: \`apps/anvil/teleprompter_pro.html\`
- Build output source: \`apps/anvil/dist/**\`
- Mirror target: \`apps/nursery/public/anvil/**\`

Do not edit files here manually; they are overwritten by sync.
`;
  fs.writeFileSync(readmePath, body, "utf8");
}

const nurseryRoot = process.cwd();
const src = path.resolve(nurseryRoot, "..", "anvil", "dist");
const dest = path.resolve(nurseryRoot, "public", "anvil");

if (!fs.existsSync(src)) {
  console.error(`[sync-anvil] missing: ${src}`);
  console.error("[sync-anvil] build Anvil first (apps/anvil) so dist exists.");
  process.exit(1);
}

emptyDir(dest);
copyDir(src, dest);

const mirroredTeleprompter = path.join(dest, "teleprompter_pro.html");
tagGeneratedTeleprompter(mirroredTeleprompter);
writeGeneratedReadme(dest);

console.log(`[sync-anvil] ${src} -> ${dest} (one-way mirror)`);
